"vo_anteater_01":{"kind":"vox","dur":4.495,"ch":1,"who":"anteater","text":"Hold on. I smell something. It's gossip.","trim":{"m4a":0.55}},
"vo_anteater_02":{"kind":"vox","dur":3.97,"ch":1,"who":"anteater","text":"I know a shortcut. It's longer, but it's prettier.","trim":{"m4a":0.98}},
"vo_anteater_03":{"kind":"vox","dur":3.99,"ch":1,"who":"anteater","text":"That store's got ants in aisle three. I'm just saying.","trim":{"m4a":0.24}},
"vo_anteater_04":{"kind":"vox","dur":6.348,"ch":1,"who":"anteater","text":"Mm. I've been sniffing this road all morning. Nothing.","trim":{"ogg":0.41}},
"vo_anteater_05":{"kind":"vox","dur":5.922,"ch":1,"who":"anteater","text":"You wanna know a secret? The sun's got a twin."},
"vo_anteater_06":{"kind":"vox","dur":3.725,"ch":1,"who":"anteater","text":"Don't mind me. I'm just noticing.","trim":{"ogg":0.4}},
"vo_anteater_07":{"kind":"vox","dur":4.56,"ch":1,"who":"anteater","text":"My nose went in that cube store. The rest of me didn't.","trim":{"m4a":0.25,"ogg":0.39}},
"vo_anteater_08":{"kind":"vox","dur":7.215,"ch":1,"who":"anteater","text":"Boot car came by twice. Third time's a pattern.","trim":{"ogg":0.23}},
"vo_anteater_09":{"kind":"vox","dur":5.695,"ch":1,"who":"anteater","text":"Two o'clock? Child, I've been late since birth.","trim":{"m4a":0.67,"ogg":0.22}},
"vo_anteater_10":{"kind":"vox","dur":7.18,"ch":1,"who":"anteater","text":"Everybody's melting but me. I'm too slow to melt.","trim":{"ogg":0.44}},
"vo_anteater_11":{"kind":"vox","dur":3.118,"ch":1,"who":"anteater","text":"I'll tell you everything. Slowly."},
"vo_anteater_12":{"kind":"vox","dur":5.067,"ch":1,"who":"anteater","text":"Well. That's enough excitement for a season."},
"vo_bear_01":{"kind":"vox","dur":2.18,"ch":1,"who":"bear","text":"Oh. Hey."},
"vo_bear_02":{"kind":"vox","dur":4.765,"ch":1,"who":"bear","text":"I'm not in a rush. I've never been in a rush."},
"vo_bear_03":{"kind":"vox","dur":3.575,"ch":1,"who":"bear","text":"That's a nice car. Does it eat?","trim":{"m4a":0.21,"ogg":0.25}},
"vo_bear_04":{"kind":"vox","dur":6.955,"ch":1,"who":"bear","text":"I had a nap here once. Best one of my life."},
"vo_bear_05":{"kind":"vox","dur":4.185,"ch":1,"who":"bear","text":"You look tired. Want my bench?","trim":{"m4a":0.2}},
"vo_bear_06":{"kind":"vox","dur":6.395,"ch":1,"who":"bear","text":"The sun blinked at me. I blinked back. We're good."},
"vo_bear_07":{"kind":"vox","dur":2.375,"ch":1,"who":"bear","text":"I'd help, but I'm comfortable."},
"vo_bear_08":{"kind":"vox","dur":7.42,"ch":1,"who":"bear","text":"Honey's at the store. Third shelf. Don't tell anyone."},
"vo_bear_09":{"kind":"vox","dur":4.92,"ch":1,"who":"bear","text":"Melting's fine. Just go slow and think about soup.","trim":{"m4a":0.24}},
"vo_bear_10":{"kind":"vox","dur":3.24,"ch":1,"who":"bear","text":"Two o'clock? I usually get there around three.","trim":{"m4a":0.24,"ogg":0.24}},
"vo_bear_11":{"kind":"vox","dur":3.325,"ch":1,"who":"bear","text":"Big day. I'm gonna sit for most of it.","trim":{"ogg":0.23}},
"vo_bear_12":{"kind":"vox","dur":8.92,"ch":1,"who":"bear","text":"See ya. Or not. Either way's nice.","trim":{"m4a":0.22}},
"vo_clerk_01":{"kind":"vox","dur":0.68,"ch":1,"who":"clerk","text":"Closed."},
"vo_clerk_02":{"kind":"vox","dur":1.23,"ch":1,"who":"clerk","text":"Two o'clock is two o'clock.","trim":{"ogg":0.24}},
"vo_clerk_03":{"kind":"vox","dur":4.09,"ch":1,"who":"clerk","text":"Welcome to the store. Please do not touch the floating merchandise."},
"vo_clerk_04":{"kind":"vox","dur":3.76,"ch":1,"who":"clerk","text":"The chips are free-range. They go where they like.","trim":{"ogg":0.23}},
"vo_clerk_05":{"kind":"vox","dur":3.84,"ch":1,"who":"clerk","text":"You have until two. I have a clock. It is very accurate."},
"vo_clerk_06":{"kind":"vox","dur":3.175,"ch":1,"who":"clerk","text":"That aisle is for looking, not for wanting."},
"vo_clerk_07":{"kind":"vox","dur":2.7,"ch":1,"who":"clerk","text":"Ah. A customer. How unexpected."},
"vo_clerk_08":{"kind":"vox","dur":2.99,"ch":1,"who":"clerk","text":"Will that be everything, or will you be lingering?"},
"vo_clerk_09":{"kind":"vox","dur":2.225,"ch":1,"who":"clerk","text":"Exact change only. Emotionally exact.","trim":{"m4a":0.23}},
"vo_clerk_10":{"kind":"vox","dur":2.335,"ch":1,"who":"clerk","text":"The pretzels chose you. Congratulations."},
"vo_clerk_11":{"kind":"vox","dur":3.11,"ch":1,"who":"clerk","text":"One minute left. I am already reaching for the sign."},
"vo_clerk_12":{"kind":"vox","dur":3.375,"ch":1,"who":"clerk","text":"Thirty seconds. I can hear the lock getting excited."},
"vo_clerk_13":{"kind":"vox","dur":2.91,"ch":1,"who":"clerk","text":"You made it. I am almost disappointed."},
"vo_clerk_14":{"kind":"vox","dur":3.845,"ch":1,"who":"clerk","text":"Enjoy your snacks. Responsibly. Slowly. Elsewhere."},
"vo_clerk_15":{"kind":"vox","dur":3.02,"ch":1,"who":"clerk","text":"Too late. The door has made its decision.","trim":{"ogg":0.2}},
"vo_clerk_16":{"kind":"vox","dur":5.33,"ch":1,"who":"clerk","text":"Come back tomorrow. Before two. Like a professional."},
"vo_crow_01":{"kind":"vox","dur":0.82,"ch":1,"who":"crow","text":"Is it art?","trim":{"m4a":0.19}},
"vo_crow_02":{"kind":"vox","dur":1.38,"ch":1,"who":"crow","text":"That car has boots.","trim":{"ogg":0.24}},
"vo_crow_03":{"kind":"vox","dur":2.86,"ch":1,"who":"crow","text":"Mm. The wheel spins, but the stool stays. Profound."},
"vo_crow_04":{"kind":"vox","dur":2.36,"ch":1,"who":"crow","text":"Look at the way it refuses to go anywhere."},
"vo_crow_05":{"kind":"vox","dur":2.5,"ch":1,"who":"crow","text":"I would hang this in my kitchen. Upside down.","trim":{"m4a":0.39}},
"vo_crow_06":{"kind":"vox","dur":4.46,"ch":1,"who":"crow","text":"The sun is watching it too. The sun has taste.","trim":{"ogg":0.46}},
"vo_crow_07":{"kind":"vox","dur":4.97,"ch":1,"who":"crow","text":"Oh, they're back. The boot car. Twice in one day.","trim":{"ogg":0.27}},
"vo_crow_08":{"kind":"vox","dur":6.74,"ch":1,"who":"crow","text":"Darling, that's not a traffic jam. That's an installation.","trim":{"m4a":0.46,"ogg":0.33}},
"vo_crow_09":{"kind":"vox","dur":4.75,"ch":1,"who":"crow","text":"Everything melts eventually. That's the point."},
"vo_crow_10":{"kind":"vox","dur":7.64,"ch":1,"who":"crow","text":"I've seen this wheel before. In a dream. It was smaller.","trim":{"m4a":0.23,"ogg":0.25}},
"vo_crow_11":{"kind":"vox","dur":3.52,"ch":1,"who":"crow","text":"Shh. The desert is thinking.","trim":{"ogg":0.1}},
"vo_crow_12":{"kind":"vox","dur":5.19,"ch":1,"who":"crow","text":"Five stars. For the composition.","trim":{"ogg":0.16}},
"vo_farmhand_01":{"kind":"vox","dur":1.32,"ch":1,"who":"farmhand","text":"Eleven seconds."},
